class Solution:
    def maxSumBST(self, root: Optional[TreeNode]) -> int:
        best = 0
        def go(n):
            nonlocal best
            if not n: return True, inf, -inf, 0
            a, b = go(n.left), go(n.right)
            if a[0] and b[0] and a[2] < n.val < b[1]:
                s = a[3] + b[3] + n.val; best = max(best, s)
                return True, min(a[1], n.val), max(b[2], n.val), s
            return False, 0, 0, 0
        go(root)
        return best

