function maxSumBST(root) {
  let best = 0;
  const vals = (n, out) => { if (!n) return out; vals(n.left, out); out.push(n.val); vals(n.right, out); return out; };
  const go = (n) => {
    if (!n) return;
    const a = vals(n, []);
    let ok = true; for (let i = 1; i < a.length; i++) if (a[i] <= a[i - 1]) { ok = false; break; }
    if (ok) best = Math.max(best, a.reduce((x, y) => x + y, 0));
    go(n.left); go(n.right);
  };
  go(root); return best;
}
